function validate([limit, queries]) {
  if (limit < 1 || limit > 1e9) return 'limit is from 1 to 10^9.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (query.length !== 2) return 'Each query is a pair [x, y].';
    if (query[0] < 0 || query[0] > limit) return 'Each ball label x is from 0 to limit.';
    if (query[1] < 1 || query[1] > 1e9) return 'Each color y is from 1 to 10^9.';
  }
  return null;
}

