function queryResults(limit, queries) {
  // colorOf: ball -> its current color. ballsWithColor: color -> how many balls have it.
  const colorOf = new Map();
  const ballsWithColor = new Map();
  const result = [];
  for (const [ball, color] of queries) {
    if (colorOf.has(ball)) {
      const oldColor = colorOf.get(ball);
      const remaining = ballsWithColor.get(oldColor) - 1;
      if (remaining === 0) {
        ballsWithColor.delete(oldColor);
      } else {
        ballsWithColor.set(oldColor, remaining);
      }
    }
    colorOf.set(ball, color);
    ballsWithColor.set(color, (ballsWithColor.get(color) ?? 0) + 1);
    result.push(ballsWithColor.size);
  }
  return result;
}

