function queryResults(limit, queries) {
  // After each query, replay every query so far to find each ball's latest color, then count distinct colors.
  const result = [];
  for (let i = 0; i < queries.length; i++) {
    const latest = {};
    for (let k = 0; k <= i; k++) latest[queries[k][0]] = queries[k][1];
    result.push(new Set(Object.values(latest)).size);
  }
  return result;
}

