function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  // limit is sometimes tiny (so balls are painted again and again) and sometimes huge (labels far apart).
  const limit = rand() < 0.5 ? int(1, large ? 60 : 5) : int(1, 1e9);
  const n = large ? 2000 : int(1, 10);
  // Queries reuse a few candidate balls and colors, so balls get repainted and colors get shared.
  const balls = Array.from({ length: large ? int(5, 400) : int(2, 5) }, () => int(0, limit));
  const colors = Array.from({ length: large ? int(5, 400) : int(1, 4) }, () => (rand() < 0.5 ? int(1, 5) : int(1, 1e9)));
  const queries = Array.from({ length: n }, () => [balls[int(0, balls.length - 1)], colors[int(0, colors.length - 1)]]);
  return [limit, queries];
}
